-- ============================================
-- LUMA — Thème 2 : LONG 2/3 x4 — Rencontrer les amis de l'autre
-- ============================================


update scenarios set content = '{"characters": {"alex": "Alex", "friend1": "Jordan", "friend2": "Sam", "friend3": "Casey"}, "start_node": "n1", "nodes": {"n1": {"speaker": "alex", "text": "Okay, deep breath — they''re going to love you, I promise.", "text_fr": "Bon, grande respiration — ils vont t''adorer, promis.", "choices": [{"text": "I hope so, I really want to make a good impression.", "text_fr": "J''espère, je veux vraiment faire bonne impression.", "next": "n2"}, {"text": "Ha, no pressure or anything!", "text_fr": "Ha, aucune pression hein !", "next": "n2b"}]}, "n2": {"speaker": "friend1", "text": "There you are! We''ve heard so much about you.", "text_fr": "Te voilà ! On a tellement entendu parler de toi.", "choices": [{"text": "All good things, I hope!", "text_fr": "Que du bon, j''espère !", "next": "n3"}, {"text": "Likewise, Alex talks about you all constantly.", "text_fr": "Pareil, Alex parle de vous tout le temps.", "next": "n3"}]}, "n2b": {"speaker": "friend1", "text": "(Laughs) Don''t worry, we''re pretty easy to impress!", "text_fr": "(Rit) T''inquiète, on est plutôt faciles à impressionner !", "choices": [{"text": "That''s a relief to hear!", "text_fr": "Ça fait plaisir à entendre !", "next": "n3"}]}, "n3": {"speaker": "friend2", "text": "So, how did you two actually meet? Alex''s story keeps changing.", "text_fr": "Alors, comment vous vous êtes vraiment rencontrés ? L''histoire d''Alex change à chaque fois.", "choices": [{"text": "A dating app, nothing too dramatic.", "text_fr": "Une appli de rencontre, rien de trop dramatique.", "next": "n4"}, {"text": "(Jokingly) Actually, it''s a really wild story...", "text_fr": "(En plaisantant) En fait, c''est une histoire vraiment folle...", "next": "n4b"}]}, "n4": {"speaker": "friend2", "text": "Ha, that tracks. So what do you do for work?", "text_fr": "Ha, ça colle. Alors tu fais quoi comme travail ?", "choices": [{"text": "(Answer honestly about your job.)", "text_fr": "(Réponds honnêtement à propos de ton travail.)", "next": "n5"}]}, "n4b": {"speaker": "friend1", "text": "Oh really? Now I need to hear this.", "text_fr": "Oh vraiment ? Maintenant je dois entendre ça.", "choices": [{"text": "(Play along with a fun exaggerated version of the story.)", "text_fr": "(Joue le jeu avec une version amusante et exagérée de l''histoire.)", "next": "n5b"}, {"text": "Okay, I''m actually just messing with you, it was a dating app.", "text_fr": "OK, en fait je vous fais marcher, c''était une appli de rencontre.", "next": "n5"}]}, "n5": {"speaker": "friend2", "text": "Nice! Alex mentioned you''re into hiking too?", "text_fr": "Cool ! Alex a mentionné que tu aimes la randonnée aussi ?", "choices": [{"text": "Yeah, we''re actually planning a trail hike soon.", "text_fr": "Ouais, on prévoit d''ailleurs une randonnée bientôt.", "next": "n6"}, {"text": "A bit, though Alex is way more experienced than me.", "text_fr": "Un peu, même si Alex est bien plus expérimenté que moi.", "next": "n6"}]}, "n5b": {"speaker": "friend1", "text": "(Laughing hard) Okay that''s clearly not true, but I love the effort!", "text_fr": "(Rit fort) OK c''est clairement pas vrai, mais j''adore l''effort !", "choices": [{"text": "Ha, had to keep things interesting!", "text_fr": "Ha, fallait bien garder les choses intéressantes !", "next": "n6"}]}, "n6": {"speaker": "friend3", "text": "(Teasing) So Alex, is this the one who''s going to fix your terrible taste in movies?", "text_fr": "(Taquin) Alors Alex, c''est celui/celle qui va corriger ton horrible goût en films ?", "choices": [{"text": "(Jump in defending Alex playfully.)", "text_fr": "(Interviens pour défendre Alex avec humour.)", "next": "n7"}, {"text": "(Laugh and agree the taste really is questionable.)", "text_fr": "(Ris et sois d''accord que le goût est vraiment discutable.)", "next": "n7b"}]}, "n7": {"speaker": "alex", "text": "(Laughs) See, this is why I like this one already!", "text_fr": "(Rit) Tu vois, c''est pour ça que je l''aime déjà !", "choices": [{"text": "Someone has to defend your honor, right?", "text_fr": "Quelqu''un doit défendre ton honneur, non ?", "next": "n8"}]}, "n7b": {"speaker": "alex", "text": "Hey! Okay, fair, my taste in movies is a little questionable.", "text_fr": "Hé ! OK, d''accord, mon goût en films est un peu discutable.", "choices": [{"text": "It''s part of your charm though, honestly.", "text_fr": "Ça fait partie de ton charme quand même, honnêtement.", "next": "n8"}]}, "n8": {"speaker": "friend2", "text": "Okay, I actually really like this one, Alex. Good choice.", "text_fr": "OK, j''aime vraiment celui/celle-là en fait, Alex. Bon choix.", "choices": [{"text": "(Feel a wave of relief at the approval.)", "text_fr": "(Ressens une vague de soulagement face à cette approbation.)", "next": "n9"}]}, "n9": {"speaker": "friend1", "text": "We''re about to play a game, are you two in?", "text_fr": "On est sur le point de jouer à un jeu, vous êtes partants ?", "choices": [{"text": "Definitely, I love games!", "text_fr": "Carrément, j''adore les jeux !", "next": "n10"}, {"text": "Sure, though fair warning, I''m terrible at most games.", "text_fr": "Bien sûr, même si je préviens, je suis nul à la plupart des jeux.", "next": "n10b"}]}, "n10": {"speaker": "friend3", "text": "Great, teams of two — you''re with Alex obviously.", "text_fr": "Super, équipes de deux — tu es avec Alex évidemment.", "choices": [{"text": "Perfect, we''re going to crush this.", "text_fr": "Parfait, on va tout écraser.", "next": "n11"}]}, "n10b": {"speaker": "alex", "text": "Don''t worry, I''ll carry the team, ha.", "text_fr": "T''inquiète, je vais porter l''équipe, ha.", "choices": [{"text": "We''ll see about that!", "text_fr": "On verra bien !", "next": "n11"}]}, "n11": {"speaker": "friend2", "text": "(The game gets competitive and fun, everyone laughing together.)", "text_fr": "(Le jeu devient compétitif et amusant, tout le monde rit ensemble.)", "choices": [{"text": "(Feel genuinely comfortable in the group now.)", "text_fr": "(Te sens vraiment à l''aise dans le groupe maintenant.)", "next": "n12"}]}, "n12": {"speaker": "friend1", "text": "Honestly, you fit right in with us. I can see why Alex likes you.", "text_fr": "Honnêtement, tu t''intègres parfaitement avec nous. Je comprends pourquoi Alex t''aime bien.", "choices": [{"text": "That really means a lot, thank you.", "text_fr": "Ça compte vraiment beaucoup, merci.", "next": "n13"}]}, "n13": {"speaker": "alex", "text": "(Quietly, just to you) They really like you. I''m relieved, honestly.", "text_fr": "(Discrètement, juste pour toi) Ils t''aiment vraiment bien. Je suis soulagé, honnêtement.", "choices": [{"text": "I was nervous too, but this went so much better than I hoped.", "text_fr": "J''étais nerveux/nerveuse aussi, mais ça s''est bien mieux passé que je l''espérais.", "next": "n14"}]}, "n14": {"speaker": "friend3", "text": "You two should come to game night every week now, honestly!", "text_fr": "Vous deux vous devriez venir à la soirée jeux chaque semaine maintenant, honnêtement !", "choices": [{"text": "I''d love that, this has been really fun.", "text_fr": "J''adorerais ça, c''était vraiment fun.", "next": "end_accepted"}, {"text": "We''ll definitely be back, this was great.", "text_fr": "On reviendra définitivement, c''était super.", "next": "end_accepted"}]}, "end_accepted": {"speaker": "alex", "text": "See, I told you they''d love you. Best introduction ever.", "text_fr": "Tu vois, je te l''avais dit qu''ils t''adoreraient. Meilleure présentation jamais faite.", "end": true, "ending_label": "Pleinement accepté(e) dans le groupe d''amis 🎉👫"}}}'::jsonb, is_playable = true
where title = 'Rencontrer les amis de l''''autre'
  and theme_id = (select id from scenario_themes where position = 2 and language_id = (select id from languages where code = 'en'));
